import type { Example } from "../example.ts"
import { html, type TemplateResult } from "lit-html"

export type ToastVariant = "brand" | "success" | "warning" | "danger" | "neutral"

export type ToastProps = {
  message: string
  variant?: ToastVariant
  action?: string
  onAction?: () => void
  class?: string
}

// The toast's look only. No motion (apps animate their own toasts) and no placement (apps stack and place them).
const look = "flex items-center gap-4 px-4 py-3 rounded-control text-sm shadow-lg"

const rise = "transition-[opacity,transform] duration-normal ease-enter starting:opacity-0 starting:translate-y-2"

const fills: Record<ToastVariant, string> = {
  brand: "bg-accent-strong text-on-fill",
  success: "bg-ok-fg text-on-fill",
  warning: "bg-warn-fg text-on-fill",
  danger: "bg-danger text-on-fill",
  neutral: "bg-fg text-canvas",
}

/** Apps put these classes on their own toast. */
export function toastClass(variant: ToastVariant = "neutral"): string {
  return `${look} ${fills[variant]}`
}

/** Apps put these classes on the toast's action button; it takes the toast's text colour. */
export function toastActionClass(): string {
  return "-my-1 shrink-0 rounded-md px-2 py-1 font-semibold underline-offset-2 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent/50 focus-visible:ring-offset-0"
}

export function toast(props: ToastProps): TemplateResult {
  const variant = props.variant ?? "neutral"
  const own = `${toastClass(variant)} ${rise}`
  const classes = props.class === undefined ? own : `${own} ${props.class}`
  return html`<div role=${variant === "danger" ? "alert" : "status"} class=${classes}>
    <span>${props.message}</span>
    ${props.action === undefined ? undefined : html`<button type="button" class=${toastActionClass()} @click=${props.onAction}>${props.action}</button>`}
  </div>`
}

const variantMessages: Record<ToastVariant, string> = {
  brand: "Nils joined Summer 2026",
  success: "Photo added to Summer 2026",
  warning: "Storage is almost full",
  danger: "Couldn't add the photo",
  neutral: "Photo added to Summer 2026",
}

export const examples: Example[] = [
  { label: "with action", render: () => toast({ message: "Photo added to Summer 2026", action: "Undo" }) },
  { label: "without action", render: () => toast({ message: "Photo added to Summer 2026" }) },
  ...(Object.keys(fills) as ToastVariant[]).map((variant) => ({
    label: variant,
    render: () => toast({ message: variantMessages[variant], variant }),
  })),
]
